<#
    MSP Toolkit Portable — self-extracting single-file bundle.

    Drop on a USB stick or drag-and-drop onto any Windows 10/11 box.
    Double-click MSPToolkit.Portable.bat (alongside this file), or right-
    click this .ps1 and pick "Run with PowerShell".

    On launch:
      1. Extracts to %TEMP%\MSPToolkit_<hash>\
      2. Re-uses the same folder on subsequent runs (fast)
      3. Launches the GUI; falls back to console if no display

    BUNDLE HASH: CE946B33C0C413CA
    BUNDLED ON:  2026-06-06 16:45:12
    FILE COUNT:  159
#>

[CmdletBinding()]
param(
    [switch]$Console,
    [switch]$ApiOnly,
    [switch]$Extract,
    [string]$ExtractTo,
    [switch]$KeepOpen,
    [switch]$NoSplash
)

$ErrorActionPreference = 'Stop'
$bundleHash = 'CE946B33C0C413CA'
$buildDate  = '2026-06-06 16:45:12'

if (-not $ExtractTo) {
    $ExtractTo = Join-Path $env:TEMP "MSPToolkit_$bundleHash"
}

Write-Host ""
Write-Host "  MSP TOOLKIT PORTABLE" -ForegroundColor Cyan
Write-Host "  Bundle: $bundleHash (built $buildDate)" -ForegroundColor DarkGray
Write-Host "  Extract: $ExtractTo" -ForegroundColor DarkGray
Write-Host ""

$marker = Join-Path $ExtractTo '.bundle-hash'
$needExtract = $true
if ((Test-Path $marker) -and (Get-Content $marker -ErrorAction SilentlyContinue) -eq $bundleHash) {
    Write-Host "  Cached copy is current — skipping extract." -ForegroundColor Green
    $needExtract = $false
}

